<?php
/** Friends-SNCMS · Andreas Holzer @WebCrew (GitHub) · Copyright © 2026 Andreas Holzer. */
declare(strict_types=1);
if (PHP_SAPI!=='cli') exit;
$directory=sys_get_temp_dir().'/friends-features-'.bin2hex(random_bytes(6)); mkdir($directory);
putenv('FRIENDS_CONFIG='.$directory.'/config.php');
require dirname(__DIR__).'/app/bootstrap.php';
use Friends\{App,Db,Features,Links,Mailer,Media,Packages,Upgrade};
$config=['dsn'=>'sqlite:'.$directory.'/test.sqlite'];
$db=new Db($config); $db->migrate();
foreach(['secret'=>bin2hex(random_bytes(32)),'site_name'=>'Feature test','registration'=>'1','theme'=>'ember','schema_version'=>'3'] as $key=>$value) $db->query('INSERT INTO f_settings (name,value) VALUES (?,?)',[$key,$value]);
file_put_contents(FRIENDS_CONFIG,'<?php return '.var_export($config,true).';');
$password='Disposable Feature Password!';
foreach(['alice','bob','eve'] as $i=>$name) $db->query('INSERT INTO f_users (username,email,password,name,bio,role,created_at) VALUES (?,?,?,?,?,?,?)',[$name,$name.'@example.test',password_hash($password,PASSWORD_DEFAULT),ucfirst($name),'',$i===0?'admin':'member','2020-01-01 00:00:00']);
$binding=hash('sha256',(string)$db->value("SELECT value FROM f_settings WHERE name='secret'"));
$_SESSION=['user_id'=>1,'locale'=>'de','installation'=>$binding]; $_GET=['r'=>'feed']; $_SERVER['REMOTE_ADDR']='127.0.0.1';
$app=new App(); $count=0;
$assert=static function(bool $ok,string $message) use(&$count): void { if(!$ok) throw new RuntimeException('FAIL '.$message); ++$count; echo 'PASS '.$message."\n"; };
$denied=static function(callable $fn,string $message) use($assert): void { try { $fn(); } catch(DomainException) { $assert(true,$message); return; } $assert(false,$message); };
$act=static function(App $app,string $action,array $data=[]): void { $_POST=$data; $_FILES=[]; $app->act($action); };
$zip=static function(array $files,string $name) use($directory): string { $path=$directory.'/'.$name.'.zip'; $z=new ZipArchive(); $z->open($path,ZipArchive::CREATE); foreach($files as $file=>$body) $z->addFromString($file,$body); $z->close(); return $path; };
try {
    $assert(Links::url('https://example.org/test?a=1&b=2')==='https://example.org/test?a=1&b=2','HTTP(S) URL retains query');
    foreach(['javascript:alert(1)','file:///etc/passwd','https://a:b@example.org/','https://example.org/'."\r\n".'X: bad'] as $bad) $denied(fn()=>Links::url($bad),'unsafe URL rejected');
    foreach(['127.0.0.1','10.0.0.1','169.254.169.254','100.100.100.100','192.168.1.1','192.0.2.1','224.0.0.1','::1','::ffff:127.0.0.1'] as $ip) $assert(!Links::publicIp($ip),'non-public preview address rejected '.$ip);
    $assert(Links::publicIp('8.8.8.8'),'ordinary public IPv4 can be fetched');
    $meta=Links::metadata('<title>Fallback</title><meta property="og:title" content="A &amp; B"><meta name="description" content="A useful description"><script>alert(1)</script>','https://example.org/');
    $assert($meta['title']==='A & B' && $meta['description']==='A useful description','preview parses safe textual metadata');
    $assert(!str_contains(Links::render('<script>x</script> https://example.org/'),'<script>') && str_contains(Links::render('https://example.org/'),'noopener'),'links escape markup and isolate new windows');
    $act($app,'profile',['name'=>'Alice','bio'=>'About me','locale'=>'en','profile_links'=>"GitHub | https://github.com/WebCrew\nHome | https://example.org"]);
    $profile=(new Features($app))->profile(1);
    $assert(count(json_decode($profile['links'],true))===2,'homepage and social profile links persist');
    $denied(fn()=>$act($app,'profile',['name'=>'Alice','profile_links'=>'Bad | javascript:alert(1)']),'profile rejects executable URLs');
    $denied(fn()=>$act($app,'profile',['name'=>'Alice','profile_links'=>implode("\n",array_fill(0,7,'https://example.org'))]),'profile link count is bounded');
    $act($app,'post',['body'=>'','post_link'=>'http://127.0.0.1/private','visibility'=>'private']);
    $post=(int)$db->value('SELECT MAX(id) FROM f_posts');
    $assert($db->value('SELECT title FROM f_post_links WHERE post_id=?',[$post])==='127.0.0.1','local preview becomes a safe unfetched domain card');
    $_SESSION['user_id']=2; $bob=new App();
    $denied(fn()=>$bob->visiblePost($post),'private link post stays private');
    foreach(['admin_uploads','admin_member','document_save','mail_settings','newsletter_create','package_install','theme_toggle'] as $action) $denied(fn()=>$act($bob,$action),'member denied '.$action);
    $_SESSION['user_id']=1;
    $act($app,'admin_uploads',['upload_mb'=>3,'upload_daily_mb'=>50,'feed_emojis'=>1,'profile_images'=>1]);
    $assert($app->setting('feed_files')==='0' && $app->setting('upload_mb')==='3','admin upload switches and numeric bounds persist');
    $denied(fn()=>$act($app,'post',['post_link'=>'https://example.org']),'disabled preview rejected server-side');
    $denied(fn()=>$act($app,'admin_uploads',['upload_mb'=>0,'upload_daily_mb'=>50]),'invalid upload limit rejected');
    $act($app,'admin_uploads',['upload_mb'=>5,'upload_daily_mb'=>100,'feed_emojis'=>1,'feed_images'=>1,'feed_files'=>1,'profile_images'=>1,'link_previews'=>1]);
    $act($app,'admin_uploads',['upload_mb'=>64,'upload_daily_mb'=>100,'post_attachments'=>8]);
    $assert($app->setting('upload_mb')==='64' && $app->setting('post_attachments')==='8','64 MB and custom attachment count persist');
    $act($app,'admin_uploads',['upload_mb'=>999,'upload_daily_mb'=>100,'post_attachments'=>12]);
    $assert($app->setting('upload_mb')==='999','no arbitrary ten MB ceiling');
    $denied(fn()=>$act($app,'admin_uploads',['upload_mb'=>64,'upload_daily_mb'=>100,'post_attachments'=>0]),'zero attachment count rejected');
    $act($app,'admin_uploads',['upload_mb'=>5,'upload_daily_mb'=>100,'post_attachments'=>1,'feed_images'=>1,'feed_files'=>1,'link_previews'=>1]);
    $_POST=['body'=>'Attachment count test']; $_FILES=['attachments'=>['error'=>[0,0]]];
    $before=(int)$db->value('SELECT COUNT(*) FROM f_posts');
    $denied(fn()=>$app->act('post'),'server rejects attachments above configured count');
    $assert((int)$db->value('SELECT COUNT(*) FROM f_posts')===$before,'excess attachments create no partial post');
    $_FILES=[];
    $act($app,'admin_uploads',['upload_mb'=>5,'upload_daily_mb'=>100,'post_attachments'=>4,'feed_images'=>1,'feed_files'=>1,'link_previews'=>1,'profile_images'=>1]);
    $doc=['slug'=>'privacy','title_de'=>'Datenschutz','title_en'=>'Privacy','body_de'=>'<script>bad()</script> https://example.org','body_en'=>'Privacy information','published'=>1];
    $act($app,'document_save',$doc);
    $id=(int)$db->value('SELECT MAX(id) FROM f_documents');
    $assert((int)$db->value('SELECT published FROM f_documents WHERE id=?',[$id])===1,'bilingual legal page can be published');
    $_SESSION['locale']='de'; $_GET=['r'=>'static','slug'=>'privacy']; $screen=new App(); $method=new ReflectionMethod($screen,'data');
    ob_start(); $screen->view('static',$method->invoke($screen)); $html=ob_get_clean();
    $assert(str_contains($html,'&lt;script&gt;') && !str_contains($html,'<script>bad()'),'legal page content cannot execute HTML');
    $act($app,'document_delete',['id'=>$id]);
    $denied(fn()=>$method->invoke(new App()),'unpublished legal page is inaccessible');
    $denied(fn()=>$act($app,'admin_member',['id'=>1,'name'=>'Alice','email'=>'alice@example.test','role'=>'member']),'existing admin cannot be demoted');
    $act($app,'admin_member',['id'=>2,'name'=>'Bob Updated','email'=>'bob-new@example.test','bio'=>'New bio','role'=>'member','status'=>'active','locale'=>'en']);
    $assert($db->value('SELECT name FROM f_users WHERE id=2')==='Bob Updated' && (int)$db->value('SELECT auth_version FROM f_users WHERE id=2')===2,'member edit persists and email change revokes sessions');
    $denied(fn()=>$act($app,'admin_member',['id'=>2,'name'=>'Bob','email'=>'bob-new@example.test','role'=>'admin']),'granting administrator requires password confirmation');
    $app->saveSetting('newsletter_enabled','1');
    $act($app,'profile',['name'=>'Alice','newsletter'=>1]);
    $assert((new Features($app))->profile(1)['newsletter']===1,'newsletter requires explicit profile opt-in');
    $act($app,'newsletter_create',['subject'=>'Community news','mail_body'=>'Hello community']);
    $assert((int)$db->value('SELECT COUNT(*) FROM f_mail_queue')===1,'newsletter includes only consenting members');
    $act($app,'profile',['name'=>'Alice']);
    $assert($db->value('SELECT status FROM f_mail_queue')==='skipped','withdrawal cancels pending deliveries');
    $act($app,'profile',['name'=>'Alice','newsletter'=>1]);
    $profile=(new Features($app))->profile(1);
    $token=hash_hmac('sha256','unsubscribe|1|'.$profile['consent_at'],$app->setting('secret'));
    $db->query('UPDATE f_profiles SET unsubscribe_hash=? WHERE user_id=1',[hash('sha256',$token)]);
    $_SESSION['user_id']=null; $guest=new App();
    $act($guest,'unsubscribe',['token'=>$token]);
    $assert((int)$db->value('SELECT newsletter FROM f_profiles WHERE user_id=1')===0,'guest token unsubscribe withdraws consent');
    $denied(fn()=>Mailer::address("person@example.org\r\nBcc: victim@example.org"),'email header injection rejected');
    $denied(fn()=>Mailer::message('from@example.org','to@example.org',"subject\nBcc: x",'body'),'subject header injection rejected');
    $message=Mailer::message('from@example.org','to@example.org','Grüße','Ein Newsletter 😊');
    $assert(str_contains($message,'Content-Transfer-Encoding: base64') && str_contains($message,base64_encode('Ein Newsletter 😊')),'email safely encodes UTF-8');
    $longSubject=str_repeat('Grüße ',25);
    $header=Mailer::subject($longSubject);
    $assert(max(array_map('strlen',explode("\r\n",$header)))<=76 && iconv_mime_decode($header,0,'UTF-8')==='Subject: '.$longSubject,'long UTF-8 subjects fold and decode correctly');
    $_SESSION['user_id']=1; $app=new App();
    $act($app,'mail_settings',['mail_transport'=>'off','smtp_host'=>'','smtp_port'=>587,'smtp_security'=>'starttls','smtp_password'=>'private-test-secret']);
    $assert(!str_contains(json_encode($db->all('SELECT * FROM f_settings')),'private-test-secret') && is_file($directory.'/smtp-secret.php'),'SMTP secret is outside the database and public directory');
    $denied(fn()=>$act($app,'mail_settings',['mail_transport'=>'smtp','mail_from'=>'from@example.org','smtp_host'=>'smtp.example.org','smtp_port'=>587,'smtp_security'=>'none']),'unencrypted SMTP is forbidden');
    $image=imagecreatetruecolor(20,10); ob_start(); imagepng($image); $png=ob_get_clean(); imagedestroy($image);
    $processed=Media::image($png.'<?php malicious(); ?>');
    $assert($processed['mime']==='image/png' && !str_contains($processed['data'],'malicious'),'image re-encoding strips appended code');
    $denied(fn()=>Media::image('<svg onload="alert(1)"/>'),'active SVG image rejected');
    $manifest=json_encode(['id'=>'test-package','name'=>'Test','version'=>'1.0.0','api'=>1,'type'=>'plugins','author'=>'Test']);
    $valid=$zip(['manifest.json'=>$manifest,'plugin.php'=>'<?php return static function() {};'],'valid');
    $assert(Packages::inspect($valid,'plugins')['id']==='test-package','documented plugin manifest accepted');
    $bad=$zip(['manifest.json'=>$manifest,'../outside.php'=>'bad','plugin.php'=>'ok'],'traversal');
    $denied(fn()=>Packages::inspect($bad,'plugins'),'ZIP traversal rejected');
    $symlink=$zip(['manifest.json'=>$manifest,'plugin.php'=>'target'],'symlink');
    $z=new ZipArchive(); $z->open($symlink); $z->setExternalAttributesName('plugin.php',ZipArchive::OPSYS_UNIX,0120777<<16); $z->close();
    $denied(fn()=>Packages::inspect($symlink,'plugins'),'ZIP symlink rejected');
    $themeManifest=json_encode(['id'=>'test-theme','name'=>'Test theme','version'=>'1.0.0','api'=>1,'type'=>'themes','author'=>'Test']);
    $badTheme=$zip(['manifest.json'=>$themeManifest,'style.css'=>'body { background:url(https://tracker.test/x) }'],'external-css');
    $denied(fn()=>Packages::inspect($badTheme,'themes'),'tracking requests in theme CSS rejected');
    $phpTheme=$zip(['manifest.json'=>$themeManifest,'style.css'=>'body {}','plugin.php'=>'<?php bad();'],'php-theme');
    $denied(fn()=>Packages::inspect($phpTheme,'themes'),'executable PHP in theme rejected');
    $legacy=new Db(['dsn'=>'sqlite:'.$directory.'/legacy.sqlite']); $legacy->executeSchema(FRIENDS_ROOT.'/database/schema.sql');
    $legacy->query("INSERT INTO f_settings (name,value) VALUES ('schema_version','2')");
    $legacy->query("INSERT INTO f_users (username,email,password,name,bio,created_at) VALUES ('keep','keep@example.test','hash','Keep','','2020-01-01')");
    Upgrade::apply($legacy); Upgrade::apply($legacy);
    $assert((int)$legacy->value('SELECT COUNT(*) FROM f_users')===1 && $legacy->value("SELECT value FROM f_settings WHERE name='schema_version'")==='3','schema 2 upgrade preserves accounts and can repeat safely');
    foreach(['overview','site_settings','uploads','member_management','legal_pages','mail_settings','extensions','themes','voice_room','open_reports','audit'] as $section) {
        $_GET=['r'=>'admin','section'=>$section,'edit'=>$section==='member_management'?2:0]; $screen=new App();
        $data=(new ReflectionMethod($screen,'data'))->invoke($screen); ob_start(); $screen->view('admin',$data); $html=ob_get_clean();
        $assert(str_contains($html,'aria-current="page"') && !str_contains($html,'private-test-secret'),'admin section renders safely '.$section);
    }
    echo "\n$count feature checks passed. SQLite and local fixtures only.\n";
} finally {
    unset($legacy,$db,$app,$bob,$guest,$screen);
    gc_collect_cycles();
    foreach(glob($directory.'/*') as $path) if(is_file($path)) @unlink($path);
    @rmdir($directory);
}
